# Testo e scaletta visiva del video lungo (un'unica fonte per script.py e scenes.py)
# Caso 026: Felice Riva e il crac del Cotonificio Vallesusa (1960-1984)
SC = [
 # ------------------------------------------------------------------ 00 INTRO
 (0, "Ottobre 1965. Un grande gruppo tessile italiano fallisce. Circa ottomila lavoratori restano senza lavoro. E il padrone ha appena trent'anni, ed è stato fino a quei giorni il presidente del Milan.", [('Ottobre', 'cal:FALLIMENTO|OTT 1965'), ('ottomila', 'big:8.000|lavoratori senza lavoro'), ('padrone', 'fig:suit|IL PADRONE · 30 ANNI'), ('Milan', 'i:ball|PRESIDENTE DI UNA SQUADRA DI SERIE A')]),
 (0, "Quattro anni dopo lo arrestano all'uscita di un cinema. Pochi giorni di carcere, poi il mandato di cattura viene annullato per un vizio di forma. E lui, con il passaporto ancora in tasca, se ne va.", [('Quattro', 'i:cinema|MILANO · 1969'), ('carcere', 'i:prison|POCHI GIORNI'), ('vizio', 'stamp:VIZIO DI FORMA'), ('passaporto', 'i:passport|IL PASSAPORTO')]),
 (0, "Nizza, Parigi, Atene. E infine Beirut, in Libano. Ci resterà tredici anni. E quando torna in Italia, i conti con la giustizia, tra amnistie, indulti e una nuova cittadinanza, finiscono per chiudersi.", [('Nizza', 'map:Atene|30|Milano,Nizza,Parigi,Atene,Beirut|Milano>Nizza>Parigi>Atene>Beirut'), ('tredici', 'big:13 anni|in Libano'), ('amnistie', 'i:amnesty|AMNISTIE E INDULTI')]),
 (0, "In questo fascicolo vedremo chi era Felice Riva, detto Felicino, come è crollato l'impero del cotone che aveva ereditato, cosa è successo agli operai, e come si è chiusa, senza una vera pena, la sua storia giudiziaria.", [('In', 'cover'), ('Felicino', 'iii:spool|IL COTONE|factory_x|IL CRAC|plane|LA FUGA'), ('giudiziaria', 't:IL CRAC VALLESUSA · 1965-1984')]),

 # ------------------------------------------------------------------ 01 LEGNANO E IL COTONE
 (1, "Partiamo dal luogo. Legnano è una città a nord-ovest di Milano, sul fiume [Olona|Olóna]. È famosa per la battaglia del 1176 e per il suo palio. Ma nel Novecento è soprattutto una città di fabbriche.", [('Partiamo', 'map:Legnano|60|Legnano'), ('battaglia', 'cal:LA BATTAGLIA|1176'), ('fabbriche', 'i:factory|UNA CITTÀ DI FABBRICHE')]),
 (1, "Fabbriche tessili, soprattutto. Il cotone arriva grezzo, viene filato, ritorto, tessuto, tinto. Intere famiglie lavorano nei cotonifici, spesso più generazioni sotto lo stesso tetto.", [('Fabbriche', 'i:cotton|IL COTONE GREZZO'), ('filato', 'iii:fuse|FILATURA|loom|TESSITURA|spool|IL FILO'), ('famiglie', 'i:family|INTERE FAMIGLIE')]),
 (1, "In una di queste città nasce, il 15 giugno 1935, Felice Riva. Le fonti indicano come casa natale un edificio all'angolo tra via Quadrio e via Rossini, a Legnano, nell'area della fabbrica di famiglia.", [('In', 'cal:15 GIUGNO|1935'), ('casa', 'i:house|LA CASA DI FAMIGLIA'), ('fabbrica', 't:LEGNANO · VIA QUADRIO E VIA ROSSINI')]),
 (1, "Quell'edificio è rimasto in piedi per decenni, sempre più malandato. Nel 2023 sono cominciati i lavori di demolizione dell'area ex Riva, per far posto a nuove costruzioni.", [("Quell'edificio", 'i:villa|L\'AREA EX RIVA'), ('2023', 'i:excavator|LA DEMOLIZIONE · 2023'), ('costruzioni', 'stamp:FINE DI UN\'EPOCA')]),
 (1, "Ma l'azienda di cui parliamo ha un nome piemontese: Cotonificio Vallesusa, o Valle Susa. Il nome viene dalla valle di Susa, a ovest di Torino, dove erano nati i primi stabilimenti.", [('Ma', 'h:Un nome\n*piemontese*'), ('valle', 'map:Susa|60|Susa,Torino,Legnano'), ('stabilimenti', 'i:factory|I PRIMI STABILIMENTI')]),
 (1, "La storia comincia nel 1880, con una società di due imprenditori, [Wild|Vild] e [Abegg|Àbeg]. Nel 1906 nasce la società anonima Cotonificio Valle Susa. Dal 1914 la ragione sociale porta il nome della famiglia [Abegg|Àbeg], che la guida per decenni.", [('1880', 'tl:1880|WILD & ABEGG;1906|SOCIETÀ ANONIMA;1914|ABEGG & C.;1947|?'), ('Abegg', 'doc:COTONIFICIO VALLE SUSA|1880 · Wild & Abegg|1906 · società anonima|1914 · Abegg & C.|RICOSTRUZIONE GRAFICA')]),
 (1, "Gli stabilimenti si moltiplicano lungo la valle: Borgone, Sant'Antonino, Bussoleno, Susa. E poi Pianezza, Torino, Rivarolo Canavese, Lanzo. Uno dopo l'altro, nell'arco di qualche decennio.", [('Gli', 'rete:rete|8|LA VALLE DI SUSA E DINTORNI|8'), ('decennio', 't:1880-1914 · I PRIMI STABILIMENTI')]),
 (1, "In quelle fabbriche lavorano soprattutto donne. Per molte giovani della valle, il cotonificio è il primo lavoro e il primo stipendio. Una storia che ancora oggi viene raccontata nelle mostre locali.", [('In', 'crowd'), ('donne', 'fig:worker|LE OPERAIE'), ('stipendio', 'i:payenv|IL PRIMO STIPENDIO'), ('mostre', 'i:museum|LA MEMORIA DELLA VALLE')]),
 (1, "Nel 1947 gli [Abegg|Àbeg] vendono. A comprare è un imprenditore di Legnano, Giulio Riva, il padre di Felice. Le fonti sono quasi tutte d'accordo su quell'anno; solo una indica una data più tarda.", [('1947', 'cal:LA VENDITA|1947'), ('Giulio', 'fig:suit|GIULIO RIVA'), ('fonti', 'stamp:1947 · 1 FONTE: PIÙ TARDI')]),
 (1, "Facciamo una misura. Da Legnano, dove vive la famiglia Riva, alla valle di Susa ci sono circa centocinquanta chilometri in linea d'aria. Un gruppo diviso tra due regioni, la Lombardia e il Piemonte, con il cuore degli affari a Milano.", [('Facciamo', 'map:Torino|50|Legnano,Susa'), ('centocinquanta', 'big:≈ 150 km|Legnano-Susa in linea d\'aria'), ('Milano', 'ii:factory|PIEMONTE: LE FABBRICHE|bankold|MILANO: GLI AFFARI')]),
 (1, "Giulio Riva non ha solo il Vallesusa. Secondo le ricostruzioni controlla anche altre aziende tessili, come l'Unione Manifatture e il Cotonificio Olcese. Un piccolo impero del filo e del tessuto.", [('Giulio', 'ii:factory|VALLESUSA|factory|ALTRE AZIENDE'), ('impero', 'h:Un *impero*\ndel cotone')]),
 (1, "E siamo nell'Italia della ricostruzione e poi del boom economico. Si comprano lenzuola, camicie, asciugamani. La domanda di tessuti cresce, e le fabbriche lavorano a pieno ritmo.", [('E', 'cal:IL BOOM|1958-1963'), ('lenzuola', 'iii:bed|LENZUOLA|smock|CAMICIE|shop|NEGOZI'), ('pieno', 'stamp:A PIENO RITMO')]),
 (1, "Un'ultima informazione sui soldi, che ci servirà per tutta la storia. Con i coefficienti [ISTAT|ìstat] sul valore della moneta, un miliardo di lire del 1965 vale oggi circa dodici milioni e trecentomila euro.", [("Un'ultima", 'i:calc|UN CONTO'), ('coefficienti', 'i:istat|COEFFICIENTI ISTAT'), ('miliardo', 'flow:1 MILIARDO DI LIRE 1965>≈ 12,3 MLN € OGGI')]),

 # ------------------------------------------------------------------ 02 I PROTAGONISTI
 (2, "Apriamo la bacheca dei protagonisti. Al centro c'è lui: Felice Riva. Ragioniere, figlio di industriale, biondo. I giornali lo chiamano Felicino, oppure il biondino.", [('Apriamo', 'board:0'), ('Felice', 'card:FELICE RIVA|detto «Felicino» o «il biondino»|Legnano, 1935|nessuna foto: sagoma'), ('biondino', 't:«FELICINO» · «IL BIONDINO»')]),
 (2, "Il secondo: suo padre, Giulio Riva. L'industriale che ha messo insieme il gruppo. Muore all'improvviso, dopo un'operazione: nel 1959 secondo alcune fonti, nel 1960 secondo altre.", [('Il', 'board:1'), ('Giulio', 'card:GIULIO RIVA|industriale di Legnano|compra il Vallesusa nel 1947|muore nel 1959 o nel 1960'), ('1959', 'stamp:1959 O 1960?')]),
 (2, "Il terzo protagonista non è una persona sola: sono gli operai e le operaie del Vallesusa. Migliaia di famiglie tra il Piemonte e la Lombardia, che dal gruppo dipendono per vivere.", [('Il', 'board:2'), ('operai', 'crowd'), ('famiglie', 'map:Torino|50|Torino,Legnano,Milano')]),
 (2, "Il quarto: le banche. Sono loro che prestano i soldi al gruppo, e sono loro che, a un certo punto, smettono di farlo. E nel 1965 saranno i creditori a presentare il conto.", [('Il', 'board:3'), ('banche', 'iii:bankold|BANCA|bankold|BANCA|bankold|BANCA'), ('conto', 'stamp:IL CONTO')]),
 (2, "Il quinto: la giustizia. Il tribunale di Milano, i giudici, i pubblici ministeri che indagheranno sul crac. Di loro diremo solo quello che risulta: decisioni, date, accuse.", [('Il', 'board:4'), ('tribunale', 'court:TRIBUNALE DI MILANO'), ('risulta', 'stamp:SOLO I FATTI')]),
 (2, "E infine un Paese lontano: il Libano. La sua capitale, Beirut, negli anni Sessanta era chiamata la Svizzera d'Oriente. Per Felice Riva diventerà una nuova casa.", [('E', 'board:5'), ('Beirut', 'map:Beirut|40|Beirut,Atene'), ('Svizzera', 'i:swiss|«LA SVIZZERA D\'ORIENTE»')]),
 (2, "Una precisazione importante. In questa storia le cifre non sempre coincidono: numero di stabilimenti, di dipendenti, anni di condanna. Quando le fonti non sono d'accordo, ve lo diremo.", [('Una', 'h:Una\n*precisazione*'), ('cifre', 'iii:question|STABILIMENTI?|question|DIPENDENTI?|question|CONDANNA?'), ('fonti', 't:QUANDO LE FONTI NON COINCIDONO, LO DICIAMO')]),

 # ------------------------------------------------------------------ 03 IL GIOVANE PADRONE
 (3, "Torniamo alla morte di Giulio Riva. All'improvviso, il gruppo resta senza il suo fondatore. E a capo di tutto si ritrova il figlio Felice, che ha ventiquattro, venticinque anni.", [('Torniamo', 'i:hospital|UN\'OPERAZIONE'), ('fondatore', 'stamp:SENZA IL FONDATORE'), ('figlio', 'big:24-25|anni')]),
 (3, "Quanto è grande l'eredità? Secondo diverse fonti, il gruppo conta intorno al 1960 circa quindicimila dipendenti. E una trentina di stabilimenti, anche se una fonte ne conta ventiquattro.", [('Quanto', 'h:Quanto è grande\nl\'*eredità*?'), ('quindicimila', 'big:15.000|dipendenti · intorno al 1960'), ('trentina', 'rete:rete|12|UNA TRENTINA DI STABILIMENTI|4')]),
 (3, "Oltre alle fabbriche ci sono società commerciali e finanziarie, in Italia e all'estero. Una galassia di aziende collegate tra loro, che fa capo alla famiglia.", [('Oltre', 'i:factory|LE FABBRICHE'), ('commerciali', 'ii:shop|SOCIETÀ COMMERCIALI|bankold|SOCIETÀ FINANZIARIE'), ('galassia', 'rete:su|12|LA GALASSIA RIVA')]),
 (3, "Facciamo un piccolo calcolo: quindicimila dipendenti. Se ognuno ha una famiglia di tre persone, intorno al gruppo vivono circa quarantacinquemila persone. Una città intera.", [('Facciamo', 'i:calc|UN CALCOLO'), ('quindicimila', 'flow:15.000 × 3>≈ 45.000 PERSONE'), ('città', 'stamp:UNA CITTÀ INTERA')]),
 (3, "Nel 1960 nelle fabbriche del Vallesusa comincia una lunga vertenza sindacale, partita dalle operaie. Le ricostruzioni dicono che il giovane padrone rifiuta a lungo di trattare, e che il clima tra la proprietà e i lavoratori diventa difficile.", [('Nel', 'cal:LA VERTENZA|1960'), ('operaie', 'fig:worker|LE OPERAIE'), ('rifiuta', 'i:megaphone|NIENTE TRATTATIVE')]),
 (3, "Intanto Felicino diventa un personaggio pubblico, sui giornali e sui rotocalchi. Le cronache lo descrivono come un amante della bella vita, giovane, ricco e sempre in vista.", [('Intanto', 'i:newspaper|I ROTOCALCHI'), ('cronache', 'iii:sportcar|GIOVANE|moneybag|RICCO|tvcam|SEMPRE IN VISTA'), ('bella', 'stamp:LA BELLA VITA')]),
 (3, "Nel 1958 si era sposato, poco più che ventenne. Della sua vita privata diremo poco: in questa storia conta soprattutto l'immagine pubblica, quella del giovane erede che sembra avere tutto.", [('Nel', 'cal:MATRIMONIO|1958'), ('privata', 'stamp:POCO SULLA VITA PRIVATA'), ('erede', 't:IL GIOVANE EREDE')]),

 # ------------------------------------------------------------------ 04 IL MILAN
 (4, "Maggio 1963, Londra, stadio di [Wembley|Uèmbli]. Il Milan batte il Benfica e vince la Coppa dei Campioni. È la prima volta per una squadra italiana.", [('Maggio', 'map:Londra|60|Londra,Milano'), ('Wembley', 'i:stadium|WEMBLEY · MAGGIO 1963'), ('Coppa', 'i:trophy|LA PRIMA COPPA DEI CAMPIONI ITALIANA')]),
 (4, "La finale si gioca il 22 maggio 1963 e finisce due a uno per il Milan. Per il calcio italiano è una data storica: fino a quel momento la coppa era sempre andata a squadre di altri Paesi.", [('La', 'cal:LA FINALE|22 MAG 1963'), ('due', 'big:2-1|Milan-Benfica · Wembley'), ('storica', 'stamp:UNA DATA STORICA')]),
 (4, "Il presidente di quella notte è Andrea Rizzoli. Ma subito dopo, nel 1963, la presidenza passa a Felice Riva. Il Milan lo ricorderà come il primo presidente dopo [Wembley|Uèmbli].", [('Il', 'fig:suit|IL PRESIDENTE DI WEMBLEY'), ('1963', 'cal:IL NUOVO PRESIDENTE|1963'), ('Wembley', 'stamp:IL PRIMO DOPO WEMBLEY')]),
 (4, "Non ha ancora trent'anni. È ricco, giovane, famoso, e ora guida la squadra campione d'Europa. Per un ragazzo di Legnano, è difficile immaginare una vetrina più grande.", [('Non', 'big:< 30|anni'), ('campione', 'i:trophy|CAMPIONI D\'EUROPA'), ('vetrina', 'stamp:LA VETRINA PIÙ GRANDE')]),
 (4, "Calcio e industria, in quegli anni, vanno spesso insieme. Grandi famiglie dell'industria guidano grandi squadre. Una squadra vincente dà visibilità, prestigio, contatti.", [('Calcio', 'ii:ball|IL CALCIO|factory|L\'INDUSTRIA'), ('famiglie', 'i:stadium|LE GRANDI SQUADRE'), ('visibilità', 'iii:tv|VISIBILITÀ|medal|PRESTIGIO|handshake|CONTATTI')]),
 (4, "La presidenza dura poco più di due anni. Le fonti indicano la fine nel 1965, l'otto ottobre secondo una ricostruzione dettagliata. Pochi giorni dopo l'inizio del fallimento.", [('La', 'tl:1963|PRESIDENTE;1964|;1965|LASCIA'), ('otto', 'cal:FINE PRESIDENZA|8 OTT 1965'), ('fallimento', 'stamp:IL CRAC')]),
 (4, "Il club resta in piedi, e passa ad altre mani. Il crac del Vallesusa non trascina con sé il Milan. Ma il nome di Felice Riva, da quel momento, sarà legato a un'altra parola.", [('Il', 'i:shirt|IL CLUB VA AVANTI'), ('trascina', 'flow:IL CRAC>NON TOCCA IL CLUB'), ('parola', "h:Un'altra *parola*")]),
 (4, "Una curiosità: il Milan di quegli anni era una delle squadre più forti d'Europa. Il Vallesusa, intanto, era già in difficoltà. Due storie parallele: una sul campo, una nei bilanci.", [('Una', 'i:pitch|SUL CAMPO'), ('difficoltà', 'i:crash|NEI BILANCI'), ('parallele', 'ii:ball|IL CAMPO|crash|I BILANCI')]),

 # ------------------------------------------------------------------ 05 LE CREPE
 (5, "Torniamo nelle fabbriche. Già dal 1964, secondo le ricostruzioni, il gruppo è in crisi di liquidità. Vuol dire una cosa semplice: in cassa non ci sono abbastanza soldi per pagare quello che si deve pagare.", [('Torniamo', 'cal:LA CRISI|1964'), ('liquidità', 'h:Crisi di\n*liquidità*'), ('cassa', 'i:safe|LA CASSA È VUOTA')]),
 (5, "Le cause? Le fonti parlano di investimenti sbagliati, di operazioni finanziarie andate male, e di una crisi del settore tessile. Il mercato cambia, la concorrenza cresce, i margini si stringono.", [('Le', 'h:Le *cause*'), ('investimenti', 'iii:crash|INVESTIMENTI SBAGLIATI|bankold|FINANZA|loom|CRISI DEL TESSILE'), ('margini', 'i:crash|MARGINI PIÙ STRETTI')]),
 (5, "Quando un'azienda non ha liquidità, di solito si rivolge alle banche e chiede nuovi prestiti. Ma prestare soldi a un gruppo in difficoltà è un rischio. E i debiti, prima o poi, vanno pagati.", [('Quando', 'flow:L\'AZIENDA>LE BANCHE'), ('rischio', 'stamp:UN RISCHIO'), ('debiti', 'i:bankold|I DEBITI')]),
 (5, "E c'è un'accusa ancora più grave. Secondo l'accusa, e secondo diverse ricostruzioni, i bilanci del gruppo sarebbero stati falsificati per nascondere i buchi.", [('E', 'h:Un\'accusa\n*più grave*'), ('bilanci', 'doc:BILANCIO|attivo ..........|passivo ..........|utile ..........|RICOSTRUZIONE GRAFICA'), ('falsificati', 'stamp:SECONDO L\'ACCUSA')]),
 (5, "Che cos'è un bilancio? È la fotografia dei conti di un'azienda: quanto possiede, quanto deve, quanto guadagna o perde. Se la fotografia è truccata, banche e fornitori prestano soldi a un'azienda che in realtà è più debole.", [('Che', 'h:Che cos\'è\nun *bilancio*?'), ('possiede', 'iii:moneybag|QUANTO HA|warn|QUANTO DEVE|chart|QUANTO GUADAGNA'), ('truccata', 'stamp:FOTOGRAFIA TRUCCATA?')]),
 (5, "Intanto, nelle valli e a Legnano, cresce la preoccupazione. Per migliaia di famiglie il cotonificio è l'unico stipendio. Se si ferma il gruppo, si ferma tutto.", [('Intanto', 'rete:rete|8|CRESCE LA PREOCCUPAZIONE'), ('famiglie', 'i:family|L\'UNICO STIPENDIO'), ('ferma', 'stamp:SE SI FERMA...')]),
 (5, "Facciamo il punto. Un gruppo da circa quindicimila dipendenti, un padrone giovanissimo e presidente del Milan, una crisi di liquidità, e il sospetto di conti truccati.", [('Facciamo', 'board:5'), ('quindicimila', 'big:15.000|dipendenti'), ('crisi', 'iii:ball|IL MILAN|safe|LA CASSA|warn|I CONTI')]),
 (5, "Prima di arrivare al crac, una richiesta veloce. Se queste storie vi interessano, iscrivetevi a Fascicolo Italia: ogni giorno un nuovo caso. E ora, ottobre 1965.", [('Prima', 'subscribe'), ('ottobre', 't:VERSO IL CRAC')]),

 # ------------------------------------------------------------------ 06 IL CRAC
 (6, "Siamo nel 1965. La crisi non si può più nascondere. I creditori vogliono essere pagati, e la questione arriva davanti a un tribunale: il gruppo deve essere dichiarato fallito?", [('Siamo', 'cal:LA RESA DEI CONTI|1965'), ('creditori', 'iii:bankold|BANCHE|truck|FORNITORI|family|LAVORATORI'), ('tribunale', 'court:IL TRIBUNALE')]),
 (6, "Che cosa vuol dire fallire? In parole semplici: un'azienda che non può più pagare i suoi debiti viene tolta dalle mani di chi la guida. Un curatore nominato dal tribunale vende quello che c'è e divide il ricavato tra i creditori.", [('Che', 'h:Che cosa vuol dire\n*fallire*?'), ('curatore', 'card:IL CURATORE|nominato dal tribunale|vende i beni|paga i creditori'), ('creditori', 'flow:I BENI DELL\'AZIENDA>I CREDITORI')]),
 (6, "Il 5 ottobre 1965 arriva la decisione: il Cotonificio Vallesusa fallisce. Una data riportata da più fonti, anche se alcune pagine sintetiche spostano tutto, per errore, al 1969.", [('5', 'cal:FALLIMENTO|5 OTT 1965'), ('fallisce', 'rete:stop|12|IL CRAC'), ('1969', 'stamp:1965, NON 1969')]),
 (6, "Il passivo, cioè i debiti, supera i quarantasei miliardi di lire secondo la maggior parte delle fonti. Una fonte parla di quarantatré miliardi. In ogni caso, è un crac enorme per l'Italia di quegli anni.", [('passivo', 'big:46 MLD|di lire di debiti · secondo la maggior parte delle fonti'), ('quarantatré', 'stamp:UNA FONTE: 43'), ('enorme', 't:UN CRAC ENORME PER L\'EPOCA')]),
 (6, "Quanto sono quarantasei miliardi del 1965? Con i coefficienti [ISTAT|ìstat], circa cinquecentosettanta milioni di euro di oggi. Più di mezzo miliardo.", [('Quanto', 'i:calc|QUANTO VALGONO?'), ('coefficienti', 'flow:46 MLD DI LIRE 1965>≈ 570 MLN € OGGI'), ('mezzo', 'stamp:COEFF. ISTAT · STIMA')]),
 (6, "E poi c'è il conto più duro. Circa ottomila lavoratori perdono il lavoro: è la cifra che ricorre in quasi tutte le fonti. Una fonte parla di quasi diecimila operai.", [('E', 'h:Il conto\n*più duro*'), ('ottomila', 'big:8.000|lavoratori senza lavoro'), ('diecimila', 'stamp:UNA FONTE: QUASI 10.000')]),
 (6, "Facciamo un altro calcolo. Quarantasei miliardi diviso ottomila lavoratori fa più di cinque milioni e mezzo di lire a testa. In euro di oggi, circa settantunomila euro per ogni posto di lavoro perso.", [('Facciamo', 'i:calc|UN ALTRO CALCOLO'), ('diviso', 'flow:46 MLD ÷ 8.000>5,75 MLN DI LIRE A TESTA'), ('settantunomila', 'big:≈ 71.000 €|per posto di lavoro · solo un ordine di grandezza')]),
 (6, "Secondo le ricostruzioni, con il fallimento gli stabilimenti chiudono. A Legnano, nelle valli piemontesi, nel Canavese, i cancelli si fermano. E migliaia di famiglie, da un giorno all'altro, devono capire come pagare l'affitto e la spesa.", [('Le', 'iii:factory_x|LEGNANO|factory_x|VALLE DI SUSA|factory_x|CANAVESE'), ('cancelli', 'stamp:CHIUSO'), ('famiglie', 'i:family_x|E LE FAMIGLIE?')]),
 (6, "Da quel momento, per molti, il nome di Felice Riva diventa il simbolo del crac. Le cronache contrappongono la sua vita mondana alle fabbriche chiuse. È un'immagine che non lo abbandonerà più.", [('Paese', 'i:newspaper|I GIORNALI DELL\'EPOCA'), ('simbolo', 'stamp:UN SIMBOLO'), ('abbandonerà', 'fig:suit|FELICE RIVA')]),
 (6, "Dal punto di vista giudiziario, l'accusa è pesante: bancarotta fraudolenta. Il rischio, secondo le ricostruzioni dell'epoca, è di anni di carcere.", [('Dal', 'court:L\'ACCUSA'), ('bancarotta', 'card:L\'ACCUSA|bancarotta fraudolenta|crac Vallesusa|secondo l\'accusa'), ('carcere', 'i:prison|IL RISCHIO')]),
 (6, "Che cos'è la bancarotta fraudolenta? È il reato di chi, prima o durante il fallimento, fa sparire beni, falsifica i libri contabili, o li tiene in modo da nascondere la situazione vera. Ai creditori resta meno, o niente.", [('Che', 'h:Che cos\'è la bancarotta\n*fraudolenta*?'), ('sparire', 'iii:box_empty|BENI SPARITI|notes|LIBRI FALSI|eye_x|CONTI NASCOSTI'), ('creditori', 'stamp:AI CREDITORI MENO')]),
 (6, "Ma un processo così non si fa in pochi mesi. Ci sono decine di società da ricostruire, contabilità da esaminare, perizie. Passeranno anni, e nel frattempo Felice Riva resta libero.", [('Ma', 'i:hourglass|ANNI DI INDAGINI'), ('decine', 'rete:stop|12|DECINE DI SOCIETÀ'), ('libero', 'stamp:ANCORA LIBERO')]),
 (6, "Che cosa resta del gruppo? Dopo il fallimento, parte delle attività tessili passa a una nuova società, chiamata [ETI|e-ti-ì] Vallesusa. Più avanti alcuni stabilimenti finiranno nell'orbita della Montedison. Ma il vecchio impero non tornerà più.", [('Che', 'h:Che cosa\n*resta*?'), ('nuova', 'flow:VALLESUSA FALLITO>E.T.I. VALLESUSA'), ('Montedison', 'i:factory|ALTRI PROPRIETARI'), ('impero', 'stamp:FINE DELL\'IMPERO')]),

 # ------------------------------------------------------------------ 07 L'ARRESTO
 (7, "Facciamo un salto di quattro anni. È il 1969. A Milano, una sera, Felice Riva esce da un cinema del centro. Ad aspettarlo ci sono le forze dell'ordine, con un mandato di cattura.", [('Facciamo', 'tl:1965|IL CRAC;1966|;1967|;1968|;1969|L\'ARRESTO'), ('cinema', 'i:cinema|UN CINEMA DEL CENTRO'), ('mandato', 'fig:police|IL MANDATO DI CATTURA')]),
 (7, "La data esatta non coincide tra le fonti: una ricostruzione del 1984 indica il 4 febbraio 1969, un'altra fonte parla di gennaio. Il luogo, invece, è lo stesso per tutti: l'uscita di un cinema.", [('La', 'ii:calendar_x|4 FEBBRAIO 1969?|calendar_x|GENNAIO 1969?'), ('luogo', 'i:cinema|IL LUOGO: L\'USCITA DEL CINEMA'), ('stesso', 'stamp:SU QUESTO CONCORDANO')]),
 (7, "Lo portano a San Vittore, il carcere di Milano. Il biondino, il presidente di [Wembley|Uèmbli], l'erede del cotone, finisce dietro le sbarre. La notizia fa il giro dei giornali.", [('Lo', 'i:prison|SAN VITTORE · MILANO'), ('sbarre', 'i:cell|DIETRO LE SBARRE'), ('notizia', 'i:newspaper|LA NOTIZIA')]),
 (7, "Ma in carcere resta pochi giorni. Il mandato di cattura viene annullato dalla Cassazione per un vizio di forma. Su questo le ricostruzioni concordano.", [('Ma', 'clock:9|POCHI GIORNI'), ('annullato', 'court:CORTE DI CASSAZIONE'), ('vizio', 'stamp:VIZIO DI FORMA')]),
 (7, "Che cos'è un vizio di forma? Un atto giudiziario deve rispettare regole precise: chi lo firma, come è motivato, entro quali termini. Se una di queste regole non è rispettata, l'atto può essere annullato. Anche se le accuse restano in piedi.", [('Che', 'h:Che cos\'è un\n*vizio di forma*?'), ('regole', 'doc:MANDATO DI CATTURA|chi lo firma|come è motivato|entro quali termini|RICOSTRUZIONE GRAFICA'), ('annullato', 'stamp:ANNULLATO'), ('accuse', 't:LE ACCUSE RESTANO IN PIEDI')]),
 (7, "Felice Riva esce dal carcere. E qui c'è il dettaglio che cambia tutto: il passaporto. Secondo le ricostruzioni non gli era stato ritirato, o gli era stato restituito.", [('Felice', 'fig:suit|FUORI DAL CARCERE'), ('passaporto', 'i:passport|IL PASSAPORTO'), ('restituito', 'stamp:NON RITIRATO')]),
 (7, "Un piccolo calcolo sui tempi. Dal fallimento dell'ottobre 1965 all'arresto dell'inizio del 1969 passano più di tre anni. Tre anni in cui l'indagine va avanti, e lui resta un uomo libero.", [('Un', 'i:calc|I TEMPI'), ('fallimento', 'flow:OTT 1965>INIZIO 1969'), ('tre', 'big:> 3 anni|dal crac all\'arresto')]),
 (7, "Ricapitoliamo. Un uomo accusato di bancarotta fraudolenta per un crac da oltre quarantasei miliardi esce dal carcere dopo pochi giorni, libero e con un documento valido per l'espatrio.", [('Ricapitoliamo', 'board:5'), ('quarantasei', 'big:46 MLD|di lire di passivo'), ('documento', 'i:passport|DOCUMENTO VALIDO')]),

 # ------------------------------------------------------------------ 08 LA FUGA
 (8, "Primavera del 1969. Felice Riva lascia l'Italia. Una fonte indica anche il giorno: il 10 marzo. E secondo quella stessa fonte non è una fuga avventurosa, ma un espatrio regolare, con il suo passaporto.", [('Primavera', 'cal:LA PARTENZA|MARZO 1969'), ('10', 'stamp:10 MARZO? · 1 FONTE'), ('espatrio', 'i:passport|ESPATRIO REGOLARE?')]),
 (8, "Il viaggio ha più tappe, e su queste le fonti concordano. Prima Nizza, in Francia. Poi Parigi. Poi Atene, in Grecia. E infine Beirut, in Libano.", [('Il', 'map:Atene|30|Milano,Nizza,Parigi,Atene,Beirut|Milano>Nizza>Parigi>Atene>Beirut'), ('Beirut', 't:MILANO › NIZZA › PARIGI › ATENE › BEIRUT')]),
 (8, "Proviamo a misurare questo viaggio. In linea d'aria, da Milano a Beirut ci sono circa duemilacinquecento chilometri. Ma con le tappe di Nizza, Parigi e Atene, il percorso supera i quattromila.", [('Proviamo', 'i:calc|LE DISTANZE'), ('duemilacinquecento', 'big:≈ 2.500 km|Milano-Beirut in linea d\'aria'), ('quattromila', 'big:> 4.000 km|con le tappe · stima indicativa')]),
 (8, "Perché proprio il Libano? Le fonti non lo spiegano con documenti. Ma il contesto aiuta. Negli anni Sessanta Beirut è un centro finanziario, con un forte segreto bancario e banche di tutto il mondo.", [('Perché', 'h:Perché proprio\nil *Libano*?'), ('Beirut', 'i:skyline|BEIRUT · ANNI \'60'), ('segreto', 'i:safe|IL SEGRETO BANCARIO')]),
 (8, "Il Libano aveva approvato nel 1956 una legge sul segreto bancario, simile a quella svizzera. Per chi aveva capitali da proteggere, era uno dei posti più attraenti del Mediterraneo.", [('Il', 'cal:SEGRETO BANCARIO|1956'), ('svizzera', 'ii:swiss|LA SVIZZERA|skyline|IL LIBANO'), ('Mediterraneo', 'map:Beirut|30|Beirut,Atene')]),
 (8, "Diverse ricostruzioni dicono che Riva arriva in Libano con capitali portati all'estero. Ma quanti, e da dove, non è mai stato chiarito pubblicamente. È una delle domande aperte di questa storia.", [('Diverse', 'i:moneybag|CAPITALI ALL\'ESTERO'), ('quanti', 'big:?|quanti soldi? · mai chiarito'), ('domande', 'stamp:DOMANDA APERTA')]),
 (8, "Intanto, a Milano, la giustizia va avanti senza di lui. Nel 1969 il tribunale di Milano lo condanna per bancarotta fraudolenta.", [('Intanto', 'court:TRIBUNALE DI MILANO'), ('condanna', 'i:gavel|LA CONDANNA · 1969')]),
 (8, "Quanti anni? Qui le fonti non coincidono: una ricostruzione dettagliata parla di sei anni di carcere, con sentenza del 15 ottobre 1969. Un'altra fonte parla di quattro anni.", [('Quanti', 'h:Quanti *anni*?'), ('sei', 'ii:gavel|6 ANNI?|gavel|4 ANNI?'), ('quattro', 'stamp:FONTI NON CONCORDI')]),
 (8, "Su un punto le fonti concordano: quella pena Felice Riva non la sconterà. È lontano, a Beirut. E la sua vita, da quel momento, diventa una vita da esule ricco.", [('Su', 'i:skyline|BEIRUT'), ('sconterà', 'stamp:PENA NON SCONTATA'), ('esule', 'i:hotel|UN ESILIO DORATO')]),
 (8, "Nel frattempo, in Italia, la sua storia diventa quasi un modo di dire. Nel 1975 una canzone di Rino Gaetano, Il cielo è sempre più blu, cita Beirut tra le sue immagini. Le cronache ricordano che molti l'hanno collegata proprio a lui.", [('Nel', 'i:music|UNA CANZONE · 1975'), ('Beirut', 'i:skyline|BEIRUT IN UNA CANZONE'), ('molti', 'stamp:UN MODO DI DIRE')]),

 # ------------------------------------------------------------------ 09 BEIRUT
 (9, "Beirut, fine anni Sessanta. È una città sul mare, con alberghi di lusso, banche, locali, turisti da tutto il mondo. I giornali dell'epoca la chiamano la Svizzera d'Oriente.", [('Beirut', 'i:skyline|BEIRUT · FINE ANNI \'60'), ('alberghi', 'iii:hotel|ALBERGHI|bankold|BANCHE|ship|IL PORTO'), ('Svizzera', 'stamp:SVIZZERA D\'ORIENTE')]),
 (9, "Qui Felice Riva vive quello che le cronache chiamano un esilio dorato. Le ricostruzioni parlano di piscine, di hall di grandi alberghi, di una vita da nababbo.", [('Qui', 'i:hotel|L\'ESILIO DORATO'), ('piscine', 'iii:umbrella|PISCINE E SPIAGGE|hotel|GRANDI ALBERGHI|wglass|LA BELLA VITA'), ('nababbo', 'stamp:UNA VITA DA NABABBO')]),
 (9, "Ma l'esilio non è solo dorato. Anche in Libano, a un certo punto, Riva finisce in carcere: cinquanta giorni, secondo più fonti. Molti più dei pochi giorni passati a San Vittore.", [('Ma', 'h:Non solo\n*dorato*'), ('cinquanta', 'big:50|giorni di carcere in Libano'), ('San', 'ii:prison|SAN VITTORE: POCHI GIORNI|cell|LIBANO: 50 GIORNI')]),
 (9, "Poi arriva la svolta giuridica. Secondo un articolo di Repubblica del 1984 e altre ricostruzioni, Felice Riva diventa cittadino libanese. Dal 1974, secondo quell'articolo.", [('Poi', 'h:La svolta\n*giuridica*'), ('cittadino', 'card:CITTADINANZA LIBANESE|dal 1974|secondo Repubblica (1984)|RICOSTRUZIONE GRAFICA'), ('1974', 'cal:CITTADINO LIBANESE|1974')]),
 (9, "Perché conta la cittadinanza? Perché molti Stati non consegnano i propri cittadini alla giustizia di altri Paesi. E perché, come vedremo, avrà un peso anche nei processi italiani.", [('Perché', 'h:Perché conta la\n*cittadinanza*?'), ('consegnano', 'flow:IL LIBANO>NON CONSEGNA'), ('processi', 'court:I PROCESSI ITALIANI')]),
 (9, "Ma nel 1975 il Libano cambia per sempre. Comincia una lunga guerra civile, che durerà fino al 1990. La Svizzera d'Oriente diventa una città divisa, con quartieri contrapposti e anni di distruzione.", [('Ma', 'cal:GUERRA CIVILE|1975'), ('guerra', 'i:warplane|BEIRUT DIVISA'), ('1990', 'tl:1975|INIZIO;1982|;1990|FINE')]),
 (9, "Per chi era arrivato cercando una vita tranquilla e lussuosa, il paradiso diventa pericoloso. Gli alberghi del lungomare, che erano il simbolo della bella vita, finiscono nella zona dei combattimenti.", [('Per', 'i:hotel|IL LUNGOMARE'), ('pericoloso', 'stamp:PERICOLO'), ('combattimenti', 'i:warplane|LA GUERRA')]),
 (9, "Riva resta comunque in Libano per anni, anche durante la guerra. In tutto, dal 1969 al 1982, sono circa tredici anni. Una fonte parla di undici: uno dei tanti numeri che non tornano.", [('Riva', 'map:Beirut|40|Beirut'), ('tredici', 'tl:1969|ARRIVO;1974|CITTADINO;1975|GUERRA;1982|PARTENZA'), ('undici', 'stamp:13 ANNI · UNA FONTE: 11')]),
 (9, "Nel 1982 la guerra si fa ancora più dura. Quell'estate Beirut viene assediata. Ed è proprio in quell'anno che Felice Riva decide di lasciare il Libano. Questa volta, come scrive una fonte, per scappare dalle bombe.", [('Nel', 'cal:L\'ASSEDIO|1982'), ('assediata', 'i:warplane|BEIRUT ASSEDIATA'), ('lasciare', 'i:plane|SI RIPARTE'), ('bombe', 'stamp:IN FUGA DALLA GUERRA')]),
 (9, "Proviamo a mettere in fila gli anni libanesi. Nel 1969 l'arrivo. Nel 1974 la cittadinanza, secondo Repubblica. Nel 1975 l'inizio della guerra. E nel mezzo, in un momento che le fonti non precisano, i cinquanta giorni di carcere.", [('Proviamo', 'tl:1969|ARRIVO;1974|CITTADINO;1975|GUERRA;1982|PARTENZA'), ('cinquanta', 'i:cell|50 GIORNI · DATA NON PRECISATA')]),
 (9, "Facciamo il punto. Un crac da quarantasei miliardi, ottomila posti di lavoro persi, una condanna mai scontata, tredici anni a Beirut. E ora un ritorno in Italia.", [('Facciamo', 'board:5'), ('quarantasei', 'iii:factory_x|46 MLD|family_x|8.000 POSTI|skyline|13 ANNI'), ('ritorno', 't:IL RITORNO')]),

 # ------------------------------------------------------------------ 10 IL RITORNO E I CONTI
 (10, "Nel 1982 Felice Riva rientra in Italia. Secondo una fonte, proprio il 15 giugno, il giorno del suo compleanno: compie quarantasette anni.", [('Nel', 'map:Beirut|30|Beirut,Milano|Beirut>Milano'), ('15', 'cal:IL RITORNO|15 GIU 1982'), ('quarantasette', 'big:47|anni')]),
 (10, "Per rientrare serve un passaporto italiano valido. Secondo la ricostruzione di Repubblica, nel maggio del 1982 la questura di Milano dà il nulla osta, su sollecitazione dell'ambasciata italiana a Beirut.", [('Per', 'i:passport|UN PASSAPORTO NUOVO'), ('questura', 'doc:NULLA OSTA|questura di Milano|maggio 1982|passaporto italiano|RICOSTRUZIONE GRAFICA'), ('ambasciata', 'flow:AMBASCIATA A BEIRUT>QUESTURA DI MILANO')]),
 (10, "E la condanna per bancarotta? Qui entrano in gioco due strumenti che in Italia, in quegli anni, vengono usati spesso: l'amnistia e l'indulto.", [('E', 'h:E la *condanna*?'), ('amnistia', 'ii:amnesty|AMNISTIA|amnesty|INDULTO')]),
 (10, "L'amnistia cancella il reato: è come se, per la legge, non fosse più punibile. L'indulto invece cancella in tutto o in parte la pena, ma il reato resta. Sono provvedimenti generali, previsti dalla Costituzione, che valgono per certi reati commessi entro una certa data.", [("L'amnistia", 'flow:AMNISTIA>IL REATO SI ESTINGUE'), ("L'indulto", 'flow:INDULTO>LA PENA SI RIDUCE'), ('Costituzione', 'i:law|PROVVEDIMENTI GENERALI')]),
 (10, "Tra condoni, amnistie e indulti, scrivono le ricostruzioni, la posizione giudiziaria di Riva si riduce quasi a zero. Una fonte parla di una pena ridotta a pochi mesi. Un'altra dice che i conti con i tribunali sono evaporati.", [('Tra', 'iii:amnesty|CONDONI|amnesty|AMNISTIE|amnesty|INDULTI'), ('zero', 'big:QUASI ZERO|la posizione giudiziaria · secondo le ricostruzioni'), ('evaporati', 'stamp:CONTI EVAPORATI')]),
 (10, "C'è poi un processo a parte, per un'infrazione valutaria: secondo l'accusa non aveva riportato in Italia azioni per un valore di circa un miliardo di lire.", [("C'è", 'court:INFRAZIONE VALUTARIA'), ('azioni', 'doc:AZIONI|valore: ≈ 1 miliardo di lire|da riportare in Italia|secondo l\'accusa|RICOSTRUZIONE GRAFICA'), ('miliardo', 'big:≈ 1 MLD|di lire · secondo l\'accusa')]),
 (10, "Il 19 aprile 1984 il tribunale di Milano lo dichiara non punibile. Il motivo, secondo Repubblica: dal 1974 è cittadino libanese. La cittadinanza, ancora una volta, cambia l'esito.", [('Il', 'cal:LA SENTENZA|19 APR 1984'), ('non', 'stamp:NON PUNIBILE'), ('cittadinanza', 'i:passport|LA CITTADINANZA LIBANESE')]),
 (10, "Facciamo i conti del tempo. Dal fallimento del 1965 alla sentenza del 1984 passano più di diciotto anni. In tutto questo periodo, Riva ha passato in carcere pochi giorni in Italia e cinquanta giorni in Libano.", [('Facciamo', 'i:calc|I CONTI DEL TEMPO'), ('diciotto', 'tl:1965|IL CRAC;1969|L\'ARRESTO;1982|IL RITORNO;1984|NON PUNIBILE'), ('cinquanta', 'ii:hourglass|OLTRE 18 ANNI|cell|POCHI GIORNI + 50')]),
 (10, "E gli operai? Migliaia di loro, nel 1965, avevano perso il lavoro da un giorno all'altro. Per loro non c'è stata nessuna amnistia: solo il tempo, e la ricerca di un nuovo posto.", [('E', 'h:E gli *operai*?'), ('lavoro', 'iii:family_x|LE FAMIGLIE|payenv|LO STIPENDIO|factory_x|IL LAVORO'), ('amnistia', 'stamp:NESSUNA AMNISTIA PER LORO')]),
 (10, "Dopo il rientro, Felice Riva vive tra Lugano e [Saint Moritz|San Mòriz], in Svizzera, fino al 1990. Poi si trasferisce a Forte dei Marmi, in Versilia, in una villa nel quartiere di Roma Imperiale.", [('Dopo', 'map:Lugano|60|Lugano,Saint Moritz,Forte dei Marmi'), ('1990', 'cal:FORTE DEI MARMI|1990'), ('villa', 'i:villa|UNA VILLA IN VERSILIA')]),
 (10, "Torniamo a Legnano, alla casa di famiglia. Dopo il fallimento, l'area ex Riva tra via Rossini e via Quadrio viene usata dalla parrocchia del quartiere per i suoi campi di lavoro. Poi, per anni, resta un edificio vuoto.", [('Torniamo', 'i:house|LA CASA DI FAMIGLIA'), ('parrocchia', 'i:convent|LA PARROCCHIA'), ('vuoto', 'stamp:UN EDIFICIO VUOTO')]),
 (10, "C'è anche un dettaglio curioso, ricordato dai giornali locali. Le finestre di quell'edificio su via Rossini, nelle domeniche di partita, servivano da biglietterie supplementari per lo stadio. Il calcio, ancora una volta, accanto alla storia dei Riva.", [("C'è", 'i:window|LE FINESTRE DI VIA ROSSINI'), ('biglietterie', 'i:stadium|BIGLIETTERIE PER LO STADIO'), ('calcio', 'i:ball|IL CALCIO, ANCORA')]),
 (10, "Gli ultimi anni li passa lì, lontano dalle prime pagine. Le cronache lo ricordano come un amante della bella vita fino alla fine, e un volto noto della vita mondana della Versilia.", [('Gli', 'i:umbrella|LA VERSILIA'), ('cronache', 'i:newspaper|LE CRONACHE LOCALI'), ('mondana', 'stamp:JET SET')]),
 (10, "Felice Riva muore il 26 giugno 2017, secondo la maggior parte delle fonti, all'ospedale della Versilia. Ha ottantadue anni, compiuti pochi giorni prima.", [('Felice', 'cal:LA MORTE|26 GIU 2017'), ('ottantadue', 'big:82|anni'), ('compleanno', 'fig:suit|FELICE RIVA · 1935-2017')]),
 (10, "Facciamo un ultimo conto. Ottantadue anni di vita, di cui circa tredici passati in Libano: più o meno un sesto. E il periodo da padrone del Vallesusa, dalla morte del padre al fallimento, dura appena cinque o sei anni.", [('Facciamo', 'i:calc|UN ULTIMO CONTO'), ('tredici', 'bars:UNA VITA|82|IN LIBANO|13|DA PADRONE DEL VALLESUSA|6'), ('cinque', 'stamp:5-6 ANNI DA PADRONE')]),
 (10, "Il Milan lo ricorda con un comunicato, come il primo presidente dopo [Wembley|Uèmbli]. I giornali di Legnano ricordano invece il crac del Vallesusa. Due memorie diverse della stessa persona.", [('Il', 'i:trophy|IL RICORDO DEL CLUB'), ('Legnano', 'i:factory_x|IL RICORDO DI LEGNANO'), ('memorie', 'ii:trophy|WEMBLEY|factory_x|IL CRAC')]),
 (10, "Scheda di riepilogo. Il fallimento: ottobre 1965. L'arresto e la scarcerazione: 1969. La partenza per Beirut e la condanna: 1969. Il ritorno: 1982. Non punibile: 1984. La morte: 2017.", [('Scheda', 'tl:1965|CRAC;1969|ARRESTO E FUGA;1982|RITORNO;1984|NON PUNIBILE;2017|MORTE')]),

 # ------------------------------------------------------------------ 11 LE DOMANDE APERTE
 (11, "Arriviamo alle domande aperte. La prima: quanti soldi ha portato all'estero Felice Riva? Le ricostruzioni parlano di capitali in tasca, ma una cifra documentata non c'è.", [('Arriviamo', 'h:Le domande\n*aperte*'), ('quanti', 'big:?|capitali all\'estero · cifra mai documentata'), ('cifra', 'stamp:NESSUNA CIFRA')]),
 (11, "La seconda: quanti anni di condanna? Sei, secondo una ricostruzione dettagliata. Quattro, secondo un'altra. E non sappiamo con certezza come si siano conclusi tutti i gradi di giudizio.", [('La', 'ii:gavel|6 ANNI?|gavel|4 ANNI?'), ('gradi', 'iii:court|PRIMO GRADO|court|APPELLO?|court|CASSAZIONE?'), ('certezza', 'stamp:NON CHIARO')]),
 (11, "La terza: quante persone hanno perso il lavoro? Ottomila per la maggior parte delle fonti, quasi diecimila per un'altra, mentre un dato parlamentare dell'epoca, citato in una ricostruzione, parla di diciottomila persone coinvolte nell'intero dissesto.", [('La', 'h:Quante *persone*?'), ('Ottomila', 'bars:LA MAGGIOR PARTE DELLE FONTI|8000|UNA FONTE|10000|TUTTO IL GRUPPO (1 FONTE)|18000'), ('diciottomila', 'stamp:NUMERI DIVERSI')]),
 (11, "La quarta: come è stato possibile che un uomo accusato di un crac così grande potesse lasciare il Paese con il suo passaporto? Le fonti raccontano il vizio di forma e il passaporto non ritirato. Ma le responsabilità di quella scelta non sono mai state chiarite.", [('La', 'i:passport|IL PASSAPORTO'), ('vizio', 'flow:VIZIO DI FORMA + PASSAPORTO>LA PARTENZA'), ('responsabilità', 'stamp:MAI CHIARITO')]),
 (11, "La quinta riguarda la data della morte del padre, il 1959 o il 1960, e quella dell'arresto, gennaio o febbraio 1969. Dettagli piccoli, ma che mostrano quanto questa storia sia stata raccontata in modi diversi.", [('La', 'ii:calendar_x|1959 O 1960?|calendar_x|GEN O FEB 1969?'), ('raccontata', 'i:newspaper|VERSIONI DIVERSE')]),
 (11, "C'è anche un'altra domanda: perché Riva finisce in carcere in Libano, e quando, esattamente? Le fonti concordano sui cinquanta giorni, ma non spiegano con precisione il motivo né la data. Un altro pezzo che manca.", [("C'è", 'i:cell|50 GIORNI IN LIBANO'), ('motivo', 'ii:question|PERCHÉ?|question|QUANDO?'), ('manca', 'stamp:UN PEZZO MANCANTE')]),
 (11, "E infine, una domanda più grande: un crac come quello del Vallesusa poteva essere evitato? Con controlli più severi sui bilanci, con banche più prudenti, con una gestione diversa? Nessun processo può rispondere davvero.", [('E', 'h:Si poteva\n*evitare*?'), ('controlli', 'iii:magnifier|CONTROLLI|bankold|BANCHE|desk|GESTIONE'), ('rispondere', 'stamp:NESSUNA RISPOSTA CERTA')]),

 # ------------------------------------------------------------------ 12 LA LEZIONE
 (12, "E oggi? Se un'azienda fallisce, che cosa succede ai lavoratori? Le regole sono molto cambiate dagli anni Sessanta. Vediamo le principali, in modo semplice. Non è consulenza legale: per un caso concreto serve un professionista o un sindacato.", [('E', 'h:E *oggi*?'), ('lavoratori', 'crowd'), ('consulenza', 'stamp:NON È CONSULENZA LEGALE')]),
 (12, "Prima regola: il trattamento di fine rapporto. Se l'azienda fallisce e non può pagarlo, c'è un Fondo di garanzia, creato nel 1982 e gestito dall'istituto nazionale della previdenza sociale. Il lavoratore può chiedere all'istituto il pagamento del [TFR|ti-effe-erre].", [('Prima', 'check:1'), ('Fondo', 'card:FONDO DI GARANZIA INPS|nato nel 1982|paga il TFR|se l\'azienda non può'), ('pagamento', 'flow:AZIENDA FALLITA>INPS PAGA IL TFR')]),
 (12, "Seconda regola: le ultime retribuzioni. Dal 1992, lo stesso Fondo può pagare anche gli ultimi tre mesi di stipendio non pagati, entro certi limiti. Negli anni Sessanta tutto questo non esisteva.", [('Seconda', 'check:2'), ('tre', 'big:3 mesi|di stipendio · entro certi limiti'), ('Sessanta', 'stamp:NEGLI ANNI \'60 NON C\'ERA')]),
 (12, "Terza regola: il nome. Dal luglio 2022 in Italia non si parla più di fallimento, ma di liquidazione giudiziale. Il Codice della crisi d'impresa vuole anche far emergere prima i segnali di crisi, prima che sia troppo tardi.", [('Terza', 'check:3'), ('liquidazione', 'flow:FALLIMENTO>LIQUIDAZIONE GIUDIZIALE'), ('segnali', 'i:warn|I SEGNALI DI CRISI')]),
 (12, "Quarta regola: la bancarotta fraudolenta è ancora un reato grave. La pena prevista va da tre a dieci anni di reclusione. E chi lascia il Paese non rende il reato meno grave: semplicemente rende più difficile il processo.", [('Quarta', 'check:4'), ('tre', 'big:3-10 anni|la pena per bancarotta fraudolenta'), ('processo', 'stamp:REATO GRAVE')]),
 (12, "Un consiglio pratico: i bilanci delle società di capitali vengono depositati al Registro delle imprese, e chiunque può richiederli. Un bilancio non dice tutto, ma perdite che si ripetono anno dopo anno sono un segnale da non ignorare.", [('Un', 'i:folder|IL REGISTRO DELLE IMPRESE'), ('bilanci', 'doc:BILANCIO DEPOSITATO|consultabile da chiunque|perdite ripetute?|debiti in crescita?|RICOSTRUZIONE GRAFICA'), ('segnale', 'stamp:UN SEGNALE')]),
 (12, "Quinta regola, per tutti: i segnali. Stipendi in ritardo, contributi non versati, fornitori che smettono di consegnare. Sono campanelli d'allarme. Chi lavora ha il diritto di chiedere informazioni, e di farsi assistere.", [('Quinta', 'check:5'), ('Stipendi', 'iii:payenv|STIPENDI IN RITARDO|tax|CONTRIBUTI|truck|FORNITORI'), ('assistere', 'stamp:FARSI ASSISTERE')]),

 # ------------------------------------------------------------------ 13 IL VERDETTO
 (13, "Ed eccoci al verdetto. Primo punto: nel 1960 Felice Riva eredita un gruppo tessile di circa quindicimila dipendenti, a ventiquattro, venticinque anni.", [('Ed', 'h:Il *verdetto*'), ('1960', 'big:15.000|dipendenti in eredità')]),
 (13, "Secondo punto: nel 1963 diventa presidente del Milan, appena campione d'Europa. Terzo punto: il 5 ottobre 1965 il Cotonificio Vallesusa fallisce, con oltre quarantasei miliardi di debiti e circa ottomila posti di lavoro persi.", [('Secondo', 'i:trophy|1963 · PRESIDENTE'), ('Terzo', 'rete:stop|12|5 OTTOBRE 1965'), ('ottomila', 'big:8.000|posti di lavoro persi')]),
 (13, "Quarto punto: nel 1969 viene arrestato e scarcerato in pochi giorni per un vizio di forma, poi parte per Beirut. Quinto punto: viene condannato per bancarotta fraudolenta, ma la pena non sarà mai scontata.", [('Quarto', 'map:Atene|30|Milano,Beirut|Milano>Beirut'), ('Quinto', 'court:CONDANNATO NEL 1969'), ('scontata', 'stamp:MAI SCONTATA')]),
 (13, "Sesto punto: torna nel 1982, e tra amnistie, indulti e cittadinanza libanese, i conti con la giustizia si chiudono. Muore nel 2017 in Versilia, a ottantadue anni.", [('Sesto', 'i:amnesty|AMNISTIE · INDULTI · CITTADINANZA'), ('Muore', 'i:umbrella|VERSILIA · 2017')]),
 (13, "E ora tocca a voi. Secondo voi, in questa storia ha pesato di più la fortuna, le regole dell'epoca, o le scelte delle persone? Scrivetelo nei commenti. Iscriviti a Fascicolo Italia: ogni giorno un nuovo caso.", [('E', 'h:E *voi*?'), ('fortuna', 'iii:question|LA FORTUNA?|law|LE REGOLE?|desk|LE SCELTE?'), ('Iscriviti', 'subscribe')]),
]
